internal (bool HasHorizontalOverflow, double ScrollBarHeightDip) MeasureHorizontalOverflowDip()
{
    var scrollViewer = FindCharactersListScrollViewer();
    if (scrollViewer is null)
    {
        return (false, 0);
    }

    var hasOverflow = scrollViewer.ScrollableWidth > 0;
    var reservedHeight = hasOverflow ? scrollViewer.ActualHeight - CharactersList.ActualHeight : 0;
    return (hasOverflow, Math.Max(0, reservedHeight));
}

double widthDip = _powerAccent.GetDisplayWidth(...);
double heightDip = RowHeightDip + (ViewModel.ShowDescription ? DescriptionHeightDip : 0);
MoveAndResize(widthDip, heightDip);
Selector.UpdateLayout();
var overflow = Selector.MeasureHorizontalOverflowDip();
if (overflow.HasHorizontalOverflow)
{
    heightDip += Math.Ceiling(overflow.ScrollBarHeightDip + LayoutRoundingDip);
    MoveAndResize(widthDip, heightDip);
}
Selector.UpdateLayout();
Selector.ScrollSelectedIntoView(_selectedIndex);

[TestMethod]
[TestCategory("PowerAccent")]
public void OverflowingCharacterListShowsHorizontalScrollbar()
{
    ReplaceSettings(this, new Settings(Activation: ActivationKey.Space, InputTimeMs: 200, SelectedLanguage: "ALL"));
    using var clipboard = PreserveClipboardText();
    using var notepad = NotepadFixture.Start(this);

    _ = RunTriggeredGesture(this, notepad, Key.E, Key.Space, toolbar =>
    {
        Assert.IsTrue(HasVisibleHorizontalScrollbar(toolbar), "Overflowed Quick Accent list should expose a horizontal scrollbar.");
    });
}

internal static bool HasVisibleHorizontalScrollbar(Session toolbar)
{
    var list = toolbar.Find<Element>(By.AccessibilityId("QuickAccentCharacterList"), 5_000);
    return WaitForToolbarScrollbarState(list, expectedVisible: true, timeoutMs: 5_000);
}
